e" NVARCHAR(1) DEFAULT 'N', "BarCode" NVARCHAR(1) DEFAULT 'N', "Condition" NCLOB MEMORY THRESHOLD 1000, "LinkTo" NVARCHAR(20), "Operator1" SMALLINT CS_INT, "Operator2" SMALLINT CS_INT, "Operation" SMALLINT CS_INT DEFAULT 0, "BCStandard" SMALLINT CS_INT DEFAULT 0, "SumInWords" NVARCHAR(1) DEFAULT 'N', "ExcFonting" NVARCHAR(1) DEFAULT 'N', "StrIndex" INTEGER CS_INT DEFAULT 0, "ContIndex" SMALLINT CS_INT DEFAULT 0, "ItemIndex" SMALLINT CS_INT DEFAULT 0, "StrLength" SMALLINT CS_INT, "StrFiller" NVARCHAR(1), "RelatedTo" NVARCHAR(20), "NextSeg" NVARCHAR(20), "HightAdjst" NVARCHAR(1) DEFAULT 'N', "DupRpttAre" NVARCHAR(1) DEFAULT 'N', "LnsRpttAre" INTEGER CS_INT DEFAULT 0, "RptDupDist" INTEGER CS_INT DEFAULT 0, "FieldId" NVARCHAR(20), "FGEnabled" NVARCHAR(1) DEFAULT 'Y', "BGEnabled" NVARCHAR(1) DEFAULT 'Y', "MKEnabled" NVARCHAR(1) DEFAULT 'Y', "BDEnabled" NVARCHAR(1) DEFAULT 'Y', "HidEmpRptt" NVARCHAR(1) DEFAULT 'N', "RpttFtrAll" NVARCHAR(1) DEFAULT 'N', "GbiDataTyp" SMALLINT CS_INT DEFAULT 0, "GbiDataLen" NVARCHAR(6), "PageBreak" SMALLINT CS_INT DEFAULT 0, "IsLogo" NVARCHAR(1) DEFAULT 'N', PRIMARY KEY ("DocCode", "ItemId")) UNLOAD PRIORITY 5  AUTO MERGE ;
